#!/usr/bin/env python3
"""Copies docs/clip-annotation-for-ai.md into Sources/MarkupGrammar/AnnotationGuide.swift,
so `octoedit guide` prints the same text. Run after editing the doc (a test checks)."""
import pathlib
root = pathlib.Path(__file__).resolve().parent.parent
text = (root / "docs/clip-annotation-for-ai.md").read_text()
assert '"""#' not in text
(root / "Sources/MarkupGrammar/AnnotationGuide.swift").write_text(
    "// Generated by Tools/sync_guide.py from docs/clip-annotation-for-ai.md. Do not edit.\n\n"
    "/// The instructions for annotating transcript.md (for people and AIs); `octoedit guide`.\n"
    "public enum AnnotationGuide {\n"
    "    public static let text = #\"\"\"\n" + text + "\"\"\"#\n}\n")
